use std::collections::BTreeMap;
use std::io::Read;

enum V {
    Null,
    Bool,
    Num(f64, bool),
    Str(String),
    Arr(Vec<V>),
    Obj(Vec<(String, V)>),
}

struct P<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> P<'a> {
    fn ws(&mut self) {
        while self.i < self.b.len() && matches!(self.b[self.i], b' ' | b'\t' | b'\n' | b'\r') {
            self.i += 1;
        }
    }
    fn lit(&mut self, s: &str) -> Option<()> {
        if self.b[self.i..].starts_with(s.as_bytes()) {
            self.i += s.len();
            Some(())
        } else {
            None
        }
    }
    fn hex4(&mut self) -> Option<u32> {
        if self.i + 4 > self.b.len() {
            return None;
        }
        let mut v = 0;
        for k in 0..4 {
            v = v * 16 + (self.b[self.i + k] as char).to_digit(16)?;
        }
        self.i += 4;
        Some(v)
    }
    fn string(&mut self) -> Option<String> {
        self.i += 1;
        let mut out: Vec<u8> = Vec::new();
        loop {
            let c = *self.b.get(self.i)?;
            self.i += 1;
            match c {
                b'"' => return String::from_utf8(out).ok(),
                0..=0x1f => return None,
                b'\\' => {
                    let e = *self.b.get(self.i)?;
                    self.i += 1;
                    let ch = match e {
                        b'"' => '"',
                        b'\\' => '\\',
                        b'/' => '/',
                        b'b' => '\u{8}',
                        b'f' => '\u{c}',
                        b'n' => '\n',
                        b'r' => '\r',
                        b't' => '\t',
                        b'u' => {
                            let h = self.hex4()?;
                            if (0xD800..0xDC00).contains(&h) {
                                if self.lit("\\u").is_none() {
                                    return None;
                                }
                                let l = self.hex4()?;
                                if !(0xDC00..0xE000).contains(&l) {
                                    return None;
                                }
                                char::from_u32(0x10000 + ((h - 0xD800) << 10) + (l - 0xDC00))?
                            } else {
                                char::from_u32(h)?
                            }
                        }
                        _ => return None,
                    };
                    let mut buf = [0u8; 4];
                    out.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                }
                _ => out.push(c),
            }
        }
    }
    fn number(&mut self) -> Option<V> {
        let s = self.i;
        let mut int = true;
        if self.b.get(self.i) == Some(&b'-') {
            self.i += 1;
        }
        match self.b.get(self.i)? {
            b'0' => self.i += 1,
            b'1'..=b'9' => {
                while matches!(self.b.get(self.i), Some(b'0'..=b'9')) {
                    self.i += 1;
                }
            }
            _ => return None,
        }
        if self.b.get(self.i) == Some(&b'.') {
            int = false;
            self.i += 1;
            let d = self.i;
            while matches!(self.b.get(self.i), Some(b'0'..=b'9')) {
                self.i += 1;
            }
            if self.i == d {
                return None;
            }
        }
        if matches!(self.b.get(self.i), Some(b'e' | b'E')) {
            int = false;
            self.i += 1;
            if matches!(self.b.get(self.i), Some(b'+' | b'-')) {
                self.i += 1;
            }
            let d = self.i;
            while matches!(self.b.get(self.i), Some(b'0'..=b'9')) {
                self.i += 1;
            }
            if self.i == d {
                return None;
            }
        }
        let t = std::str::from_utf8(&self.b[s..self.i]).ok()?;
        Some(V::Num(t.parse().ok()?, int))
    }
    fn val(&mut self, depth: usize) -> Option<V> {
        if depth > 200 {
            return None;
        }
        self.ws();
        match *self.b.get(self.i)? {
            b'{' => {
                self.i += 1;
                let mut m = Vec::new();
                self.ws();
                if self.b.get(self.i) == Some(&b'}') {
                    self.i += 1;
                    return Some(V::Obj(m));
                }
                loop {
                    self.ws();
                    if self.b.get(self.i) != Some(&b'"') {
                        return None;
                    }
                    let k = self.string()?;
                    self.ws();
                    if self.b.get(self.i) != Some(&b':') {
                        return None;
                    }
                    self.i += 1;
                    let v = self.val(depth + 1)?;
                    m.push((k, v));
                    self.ws();
                    match self.b.get(self.i)? {
                        b',' => self.i += 1,
                        b'}' => {
                            self.i += 1;
                            return Some(V::Obj(m));
                        }
                        _ => return None,
                    }
                }
            }
            b'[' => {
                self.i += 1;
                let mut a = Vec::new();
                self.ws();
                if self.b.get(self.i) == Some(&b']') {
                    self.i += 1;
                    return Some(V::Arr(a));
                }
                loop {
                    a.push(self.val(depth + 1)?);
                    self.ws();
                    match self.b.get(self.i)? {
                        b',' => self.i += 1,
                        b']' => {
                            self.i += 1;
                            return Some(V::Arr(a));
                        }
                        _ => return None,
                    }
                }
            }
            b'"' => Some(V::Str(self.string()?)),
            b't' => self.lit("true").map(|_| V::Bool),
            b'f' => self.lit("false").map(|_| V::Bool),
            b'n' => self.lit("null").map(|_| V::Null),
            _ => self.number(),
        }
    }
}

fn get<'a>(o: &'a [(String, V)], k: &str) -> Option<&'a V> {
    o.iter().find(|(n, _)| n == k).map(|(_, v)| v)
}

fn run(inp: &[u8]) -> Option<BTreeMap<String, f64>> {
    let mut p = P { b: inp, i: 0 };
    let v = p.val(0)?;
    p.ws();
    if p.i != inp.len() {
        return None;
    }
    let mut res: BTreeMap<String, f64> = BTreeMap::new();
    let V::Arr(orders) = v else { return None };
    for o in &orders {
        let V::Obj(o) = o else { return None };
        match get(o, "id")? {
            V::Num(_, true) => {}
            _ => return None,
        }
        let V::Str(c) = get(o, "customer")? else { return None };
        if let Some(n) = get(o, "note") {
            if !matches!(n, V::Str(_)) {
                return None;
            }
        }
        let V::Arr(items) = get(o, "items")? else { return None };
        let mut tot = 0.0;
        for it in items {
            let V::Obj(it) = it else { return None };
            if !matches!(get(it, "sku")?, V::Str(_)) {
                return None;
            }
            let V::Num(q, true) = get(it, "qty")? else { return None };
            let V::Num(pr, _) = get(it, "price")? else { return None };
            tot += q * pr;
        }
        *res.entry(c.clone()).or_insert(0.0) += tot;
    }
    let _ = (V::Null, V::Bool);
    Some(res)
}

fn main() {
    let mut inp = Vec::new();
    let _ = std::io::stdin().read_to_end(&mut inp);
    match run(&inp) {
        Some(m) => {
            let mut s = String::new();
            for (k, v) in m {
                s.push_str(&format!("{} {:.2}\n", k, v));
            }
            print!("{}", s);
        }
        None => {
            println!("invalid input");
            std::process::exit(1);
        }
    }
}

